import { v4 as uuidv4 } from 'uuid';
import { AccountModel, IAccount } from '../models/Account';
import { NotFoundError } from '../errors/AppError';
import { CreateAccountInput } from '../schemas/accountSchema';

export class AccountService {
  /**
   * Create a new account with an initial balance of 0.
   * id and created_at are generated by the system.
   */
  async createAccount(input: CreateAccountInput): Promise<IAccount> {
    const account = new AccountModel({
      id: uuidv4(),
      name: input.name.trim(),
      balance: 0, // Initial balance is strictly 0
      created_at: new Date(),
    });

    await account.save();
    return account;
  }

  /**
   * Retrieve account balance by account ID.
   * Throws 404 NotFoundError if the account does not exist.
   */
  async getAccountBalance(accountId: string): Promise<{ account_id: string; balance: number }> {
    const account = await AccountModel.findOne({ id: accountId }).lean();

    if (!account) {
      throw new NotFoundError(`Account with ID '${accountId}' was not found.`);
    }

    return {
      account_id: account.id,
      balance: account.balance,
    };
  }

  /**
   * Retrieve full account details by account ID.
   * Throws 404 NotFoundError if the account does not exist.
   */
  async getAccountById(accountId: string): Promise<IAccount> {
    const account = await AccountModel.findOne({ id: accountId });

    if (!account) {
      throw new NotFoundError(`Account with ID '${accountId}' was not found.`);
    }

    return account;
  }
}

export const accountService = new AccountService();

